# Story bank 02. New situations, same kinds and rules as stories01 (checked facts from batch01.py only, no prices).
# kinds: tip (one useful fact + follow), quiz (question card, answer card posted 2 slots later), contact (reply-with-keyword card)
T = []
def tip(id, segment, title, body): T.append(dict(id=id, kind="tip", segment=segment, title=title, body=body))
def quiz(id, segment, q, a, why): T.append(dict(id=id, kind="quiz", segment=segment, q=q, a=a, why=why))
def contact(id, segment, line, kw): T.append(dict(id=id, kind="contact", segment=segment, line=line, kw=kw))

# ---------------- tips ----------------
tip("t008", "freelancer", "ലോഗോ റെഡി,\nപേര് ചെക്ക് ചെയ്തോ?", "നിലവിലുള്ള കമ്പനിയുടെയോ LLP-യുടെയോ പേരുമായി സാമ്യം ഉണ്ടെങ്കിൽ പേര് റിജക്ട് ആകും. ലോഗോ പിന്നെയും മാറ്റേണ്ടി വരും.")
tip("t009", "freelancer", "പേരിൽ \"ബാങ്ക്\"\nഇടാൻ പ്ലാനുണ്ടോ?", "ബാങ്ക്, ഇൻഷുറൻസ് പോലുള്ള വാക്കുകൾ നിയന്ത്രിതമാണ്. സാധാരണ സ്റ്റാർട്ടപ്പിന് അത് ഒഴിവാക്കുന്നതാണ് ബുദ്ധി.")
tip("t010", "cofounders", "രണ്ട് പേരും\nദുബായിലാണോ?", "പ്രൈവറ്റ് ലിമിറ്റഡിൽ ഒരു ഡയറക്ടറെങ്കിലും ഇന്ത്യയിൽ താമസിക്കുന്നയാൾ വേണം. ടീം പ്ലാൻ ചെയ്യുമ്പോൾ ഇത് ഓർക്കുക.")
tip("t011", "cofounders", "കമ്പനി തുടങ്ങി,\nകച്ചവടം തുടങ്ങിയില്ലേ?", "എങ്കിലും 180 ദിവസത്തിനുള്ളിൽ ബിസിനസ് തുടങ്ങിയെന്ന ഡിക്ലറേഷൻ (INC-20A) ഫയൽ ചെയ്യണം. കലണ്ടറിൽ ഇപ്പോഴേ മാർക്ക് ചെയ്യൂ.")
tip("t012", "proprietor", "കട വീടിന്റെ\nമുൻമുറിയിലാണോ?", "ആ വീടിന്റെ അഡ്രസ്സ് തന്നെ രജിസ്റ്റേർഡ് ഓഫീസ് ആക്കാം. ഉടമയുടെ NOC-യും പുതിയ കറന്റ് ബില്ലും കരുതുക.")
tip("t013", "proprietor", "ഇൻവെസ്റ്റർ ഷെയർ\nചോദിച്ചോ?", "പ്രൊപ്രൈറ്റർഷിപ്പിനോ പാർട്ണർഷിപ്പിനോ ഷെയർ കൊടുക്കാൻ പറ്റില്ല. ഇക്വിറ്റി നിക്ഷേപത്തിന് പ്രൈവറ്റ് ലിമിറ്റഡ് വേണം.")
tip("t014", "salaried", "ശനിയും ഞായറും\nമാത്രം ബിസിനസ്?", "പാർട്ട് ടൈം ആയാലും കമ്പനി ആയാൽ ആനുവൽ ഫയലിംഗ് എല്ലാ വർഷവും വേണം. വീക്കെൻഡ് കമ്പനിക്കും വീക്ക്ഡേ ഡെഡ്‌ലൈൻ ഉണ്ട്.")
tip("t015", "salaried", "രാജി വെക്കും മുമ്പ്\nഒരു കണക്ക്", "പ്രൈവറ്റ് ലിമിറ്റഡ് രജിസ്ട്രേഷന് സാധാരണ 7 മുതൽ 15 പ്രവൃത്തി ദിവസം. നോട്ടീസ് പീരിയഡിൽ തന്നെ തുടങ്ങാം.")
tip("t016", "solo", "\"കോ-ഫൗണ്ടർ ഇല്ലാതെ\nകമ്പനി പറ്റില്ല\"", "പറ്റും. ഒറ്റയ്ക്കുള്ളവർക്ക് വൺ പേഴ്സൺ കമ്പനി (OPC). പാർട്ണറെ തേടി വർഷങ്ങൾ കളയേണ്ട.")
tip("t017", "solo", "ഒറ്റയ്ക്കാണ്, പക്ഷേ\nഫണ്ടിംഗ് സ്വപ്നമുണ്ട്", "ഇക്വിറ്റി ഫണ്ടിന് പ്രൈവറ്റ് ലിമിറ്റഡ് വേണം. അതിന് കുറഞ്ഞത് 2 ഡയറക്ടർമാരും 2 ഷെയർഹോൾഡർമാരും.")
tip("t018", "nri", "അവധിക്ക് നാട്ടിൽ\nവരുന്നുണ്ടോ?", "നാട്ടിലെ കമ്പനി രജിസ്ട്രേഷന് സാധാരണ 7 മുതൽ 15 പ്രവൃത്തി ദിവസം. ഡോക്യുമെന്റ്സ് നേരത്തെ റെഡിയാക്കിയാൽ അവധി ടെൻഷനില്ലാതെ കഴിയും.")
tip("t019", "nri", "ഗൾഫിലെ സമ്പാദ്യം,\nനാട്ടിലെ ബിസിനസ്", "NRI-ക്ക് ഷെയർഹോൾഡർ ആകാം. നിങ്ങളുടെ പങ്ക് ഷെയർ ആയി രേഖയിൽ, വാക്കാൽ അല്ല.")
tip("t020", "freelancer", "സർട്ടിഫിക്കറ്റ് കിട്ടി.\nഇനി ഫ്രീ?", "ഇല്ല. ഇൻകോർപ്പറേഷൻ കഴിഞ്ഞ് 30 ദിവസത്തിനുള്ളിൽ ആദ്യ ഓഡിറ്ററെ നിയമിക്കണം.")
tip("t021", "cofounders", "INC-20A മറന്നാൽ\nആരാ പെടുക?", "കമ്പനിക്ക് 50,000 രൂപ പിഴ. ഉത്തരവാദിയായ ഓരോ ഓഫീസർക്കും ദിവസം 1,000 രൂപ, പരമാവധി 1 ലക്ഷം രൂപ.")
tip("t022", "proprietor", "ഈ വർഷം\nകച്ചവടം മോശമായിരുന്നോ?", "വരുമാനം കുറഞ്ഞാലും ആനുവൽ ഫയലിംഗ് മുടക്കരുത്. താമസിച്ചാൽ ഓരോ ഫോമിനും ദിവസം 100 രൂപ ലേറ്റ് ഫീ കൂടും.")
tip("t023", "salaried", "സമ്പാദ്യം ലക്ഷങ്ങൾ\nആകാൻ കാത്തിരിക്കുന്നോ?", "പ്രൈവറ്റ് ലിമിറ്റഡിന് മിനിമം പെയ്ഡ്-അപ്പ് ക്യാപിറ്റൽ നിർബന്ധമില്ല. കാത്തിരിപ്പ് ഐഡിയയെ തണുപ്പിക്കും.")

# ---------------- quizzes (true/false, pick-one, who-can) ----------------
quiz("q005", "cofounders", "ഇക്വിറ്റി ഷെയർ കൊടുത്ത്\nഇൻവെസ്റ്ററിൽ നിന്ന് ഫണ്ട്\nഎടുക്കാൻ പറ്റുന്നത് ഏതിന്?\n\nA) LLP\nB) പാർട്ണർഷിപ്പ്\nC) പ്രൈവറ്റ് ലിമിറ്റഡ്", "C) പ്രൈവറ്റ് ലിമിറ്റഡ്", "LLP-ക്കും പാർട്ണർഷിപ്പിനും പ്രൊപ്രൈറ്റർഷിപ്പിനും ഷെയർ കൊടുക്കാൻ പറ്റില്ല.")
quiz("q006", "freelancer", "ശരിയോ തെറ്റോ?\n\n\"വീടിന്റെ അഡ്രസ്സ്\nരജിസ്റ്റേർഡ് ഓഫീസ്\nആക്കാൻ പറ്റില്ല\"", "തെറ്റ്", "ഉടമയുടെ NOC-യും പുതിയ യൂട്ടിലിറ്റി ബില്ലും ഉണ്ടെങ്കിൽ വീട് മതി.")
quiz("q007", "solo", "ഒറ്റയ്ക്ക് കമ്പനി\nതുടങ്ങാൻ ഏത്?\n\nA) LLP\nB) OPC\nC) ഒറ്റയ്ക്ക് പറ്റില്ല", "B) OPC", "വൺ പേഴ്സൺ കമ്പനി. ബിസിനസും നിങ്ങളും നിയമപരമായി വേറെ.")
quiz("q008", "proprietor", "ശരിയോ തെറ്റോ?\n\n\"ഈ വർഷം വരുമാനം\nഇല്ലെങ്കിൽ ആനുവൽ\nഫയലിംഗ് വേണ്ട\"", "തെറ്റ്", "സീറോ വരുമാനം ആയാലും ഫയലിംഗ് നിർബന്ധം. താമസിച്ചാൽ ഓരോ ഫോമിനും ദിവസം 100 രൂപ.")
quiz("q009", "freelancer", "ഈ പേരുകളിൽ\nറിജക്ട് ആകാൻ\nസാധ്യത കൂടുതൽ?\n\nA) Kayal Design Studio\nB) Kayal Bank\nC) Kayal Craft Works", "B) Kayal Bank", "\"ബാങ്ക്\" നിയന്ത്രിത വാക്കാണ്. പ്രത്യേക അനുമതി ഇല്ലാതെ പറ്റില്ല.")
quiz("q010", "cofounders", "ആദ്യ ഓഡിറ്ററെ\nഎപ്പോൾ നിയമിക്കണം?\n\nA) 30 ദിവസത്തിനുള്ളിൽ\nB) ആദ്യ വർഷം കഴിഞ്ഞ്\nC) ലാഭം വന്നിട്ട്", "A) 30 ദിവസത്തിനുള്ളിൽ", "ഇൻകോർപ്പറേഷൻ തീയതി മുതൽ 30 ദിവസം. ലാഭം വരാൻ കാത്തിരിക്കേണ്ട.")
quiz("q011", "salaried", "പ്രൈവറ്റ് ലിമിറ്റഡിന്\nമിനിമം മൂലധനം?\n\nA) 1 ലക്ഷം രൂപ\nB) 10 ലക്ഷം രൂപ\nC) നിർബന്ധിത മിനിമം ഇല്ല", "C) നിർബന്ധിത മിനിമം ഇല്ല", "ഓഫീസിലെ \"എല്ലാം അറിയുന്ന\" ആളോട് ഇനി ധൈര്യമായി പറയാം.")
quiz("q012", "nri", "സൗദിയിലുള്ള 2 പേർ മാത്രം\nഡയറക്ടർമാർ. നാട്ടിൽ\nപ്രൈവറ്റ് ലിമിറ്റഡ് പറ്റുമോ?\n\nA) പറ്റും\nB) റെസിഡന്റ് ഡയറക്ടർ വേണം", "B) ഒരു റെസിഡന്റ് ഡയറക്ടർ വേണം", "ഒരു ഡയറക്ടറെങ്കിലും ഇന്ത്യയിൽ താമസിക്കുന്നയാൾ ആകണം. നാട്ടിലുള്ള ആരെയെങ്കിലും ഉൾപ്പെടുത്താം.")

